from fastapi import APIRouter, FastAPI
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient
from starlette.requests import Request
from starlette.responses import Response


class AuditedRoute(APIRoute):
    accessed: list[str] = []

    def get_route_handler(self) -> callable:  # type: ignore[override]
        original_handler = super().get_route_handler()

        async def audited_handler(request: Request) -> Response:
            AuditedRoute.accessed.append(self.path)
            return await original_handler(request)

        return audited_handler


app = FastAPI()
router = APIRouter(route_class_map={"POST": AuditedRoute})


@router.get("/items")
def get_items() -> dict[str, str]:
    return {"method": "GET"}


@router.post("/items")
def post_items() -> dict[str, str]:
    return {"method": "POST"}


app.include_router(router)
client = TestClient(app)


def setup_function(_function: object) -> None:
    AuditedRoute.accessed = []


def test_get_does_not_use_audited_route() -> None:
    AuditedRoute.accessed = []
    response = client.get("/items")
    assert response.status_code == 200
    assert response.json() == {"method": "GET"}
    assert AuditedRoute.accessed == []


def test_post_uses_audited_route_and_records_path() -> None:
    AuditedRoute.accessed = []
    response = client.post("/items")
    assert response.status_code == 200
    assert response.json() == {"method": "POST"}
    assert AuditedRoute.accessed == ["/items"]


def test_only_post_records_path_for_same_path() -> None:
    AuditedRoute.accessed = []
    get_response = client.get("/items")
    post_response = client.post("/items")
    assert get_response.status_code == 200
    assert post_response.status_code == 200
    # Only the POST route used the AuditedRoute, so the path appears exactly
    # once (from the POST), and the GET did not contribute an entry.
    assert AuditedRoute.accessed.count("/items") == 1
    assert AuditedRoute.accessed == ["/items"]


def test_registered_routes_use_expected_classes() -> None:
    get_route = next(
        route
        for route in router.routes
        if "GET" in getattr(route, "methods", set())
    )
    post_route = next(
        route
        for route in router.routes
        if "POST" in getattr(route, "methods", set())
    )
    assert type(get_route) is APIRoute
    assert isinstance(post_route, AuditedRoute)
